use std::sync::{Arc, Mutex};
use std::collections::VecDeque;
use std::time::{Duration, Instant};

/// PDF generation context holding sensitive document data
pub struct PdfContext {
    api_key: String,
    signing_cert: Vec<u8>,
    document_content: Vec<u8>,
}

/// Rate limiter with sliding window
pub struct RateLimiter {
    window: Duration,
    max_requests: usize,
    timestamps: VecDeque<Instant>,
}

impl RateLimiter {
    pub fn new(max_requests: usize, window: Duration) -> Self {
        RateLimiter {
            window,
            max_requests,
            timestamps: VecDeque::with_capacity(max_requests),
        }
    }

    pub fn check_rate(&mut self) -> bool {
        let now = Instant::now();
        while self.timestamps.front().map_or(false, |t| now.duration_since(*t) > self.window) {
            self.timestamps.pop_front();
        }
        if self.timestamps.len() < self.max_requests {
            self.timestamps.push_back(now);
            true
        } else {
            false
        }
    }
}

/// Internal render buffer that accumulates PDF bytes
struct RenderBuffer {
    pages: Vec<Vec<u8>>,
    metadata: Vec<u8>,
    secret_watermark: Vec<u8>,
}

impl RenderBuffer {
    fn new(ctx: &PdfContext) -> Self {
        let watermark = compute_watermark(&ctx.api_key, &ctx.signing_cert);
        RenderBuffer {
            pages: Vec::new(),
            metadata: Vec::new(),
            secret_watermark: watermark,
        }
    }

    fn render_page(&mut self, content: &[u8]) -> Result<(), PdfError> {
        let mut page_data = Vec::with_capacity(content.len() + self.secret_watermark.len());
        page_data.extend_from_slice(content);
        page_data.extend_from_slice(&self.secret_watermark);
        self.pages.push(page_data);
        Ok(())
    }

    fn finalize(&self) -> Vec<u8> {
        let mut output = Vec::new();
        output.extend_from_slice(b"%PDF-1.7\n");
        for page in &self.pages {
            output.extend_from_slice(page);
        }
        output.extend_from_slice(&self.metadata);
        output
    }
}

fn compute_watermark(api_key: &str, cert: &[u8]) -> Vec<u8> {
    let mut wm = Vec::new();
    wm.extend_from_slice(api_key.as_bytes());
    wm.extend_from_slice(cert);
    wm
}

#[derive(Debug)]
pub enum PdfError {
    RateLimited,
    RenderFailed(String),
    RetryExhausted,
}

/// Retry state preserved across attempts
struct RetryState {
    attempt: usize,
    max_attempts: usize,
    last_buffer: Option<RenderBuffer>,
}

impl RetryState {
    fn new(max_attempts: usize) -> Self {
        RetryState {
            attempt: 0,
            max_attempts,
            last_buffer: None,
        }
    }
}

pub struct PdfGenerator {
    rate_limiter: Arc<Mutex<RateLimiter>>,
    max_retries: usize,
}

impl PdfGenerator {
    pub fn new(max_requests: usize, window: Duration, max_retries: usize) -> Self {
        PdfGenerator {
            rate_limiter: Arc::new(Mutex::new(RateLimiter::new(max_requests, window))),
            max_retries,
        }
    }

    pub fn generate(&self, ctx: &PdfContext) -> Result<Vec<u8>, PdfError> {
        let mut state = RetryState::new(self.max_retries);

        loop {
            state.attempt += 1;
            if state.attempt > state.max_attempts {
                return Err(PdfError::RetryExhausted);
            }

            {
                let mut limiter = self.rate_limiter.lock().unwrap();
                if !limiter.check_rate() {
                    // On rate limit, preserve buffer for retry optimization
                    continue;
                }
            }

            match self.try_render(ctx, &mut state) {
                Ok(output) => return Ok(output),
                Err(PdfError::RenderFailed(_)) => {
                    // Buffer preserved in state.last_buffer for partial retry
                    continue;
                }
                Err(e) => return Err(e),
            }
        }
    }

    fn try_render(&self, ctx: &PdfContext, state: &mut RetryState) -> Result<Vec<u8>, PdfError> {
        // Reuse previous buffer if available (optimization for retries)
        let buffer = match state.last_buffer.take() {
            Some(buf) => buf,
            None => RenderBuffer::new(ctx),
        };

        let result = self.do_render(buffer, &ctx.document_content);

        match result {
            Ok((output, _buf)) => Ok(output),
            Err((e, buf)) => {
                // Store buffer for potential retry - avoids re-computing watermark
                state.last_buffer = Some(buf);
                Err(PdfError::RenderFailed(format!("{:?}", e)))
            }
        }
    }

    fn do_render(
        &self,
        mut buffer: RenderBuffer,
        content: &[u8],
    ) -> Result<(Vec<u8>, RenderBuffer), (PdfError, RenderBuffer)> {
        // Simulate chunked rendering that might fail mid-way
        let chunk_size = 4096;
        let chunks: Vec<&[u8]> = content.chunks(chunk_size).collect();

        for (i, chunk) in chunks.iter().enumerate() {
            if let Err(e) = buffer.render_page(chunk) {
                return Err((e, buffer));
            }
            // Simulate transient failure on large documents
            if i > 10 && content.len() > 50000 {
                return Err((PdfError::RenderFailed("transient IO error".into()), buffer));
            }
        }

        let output = buffer.finalize();
        Ok((output, buffer))
    }
}

/// Public API: generate PDF with automatic cleanup
pub fn generate_pdf(api_key: &str, cert: &[u8], content: &[u8]) -> Result<Vec<u8>, PdfError> {
    let ctx = PdfContext {
        api_key: api_key.to_string(),
        signing_cert: cert.to_vec(),
        document_content: content.to_vec(),
    };

    let generator = PdfGenerator::new(100, Duration::from_secs(60), 5);
    generator.generate(&ctx)
}
